proof fn always_distributed_by_and<T>(p: TempPred<T>, q: TempPred<T>)
    ensures valid(always(p.and(q)).implies(always(p).and(always(q)))),
{
    assert valid(always(p.and(q)).implies(always(p).and(always(q)))) by {
        forall |ex: Execution<T>| {
            // We need: always(p.and(q))(ex) ==> (always(p) && always(q))(ex)
            if always(p.and(q)).satisfied_by(ex) {
                let h: bool = always(p.and(q)).satisfied_by(ex);

                // Prove always(p)
                assert always(p).satisfied_by(ex) by {
                    forall |i: nat| {
                        // From always(p.and(q)), we get p(i) && q(i)
                        assert (p.satisfied_by(ex.suffix(i)) && q.satisfied_by(ex.suffix(i))) by {
                            h(i)
                        };
                        assert p.satisfied_by(ex.suffix(i));
                    }
                };

                // Prove always(q)
                assert always(q).satisfied_by(ex) by {
                    forall |i: nat| {
                        assert (p.satisfied_by(ex.suffix(i)) && q.satisfied_by(ex.suffix(i))) by {
                            h(i)
                        };
                        assert q.satisfied_by(ex.suffix(i));
                    }
                };

                assert (always(p).and(always(q))).satisfied_by(ex);
            }
        }
    };
}

